#pragma once
// What the player physics needs from every block, dumped from the NSSS jar
// (tools/nsss DumpNsssPhysics, generated by tools/gen_physics.py).
#include <cstdint>

struct BoxRef { uint16_t start, count; };
struct BlockPhysics {
    uint8_t material;  // index: same number = same Material instance
    uint8_t solid, liquid, water, lava, ice;
    float slipperiness;
    uint8_t opaque;    // isOpaqueCube
    BoxRef boxes[16];  // collision boxes per metadata, block on its own (fences/stairs fixed up in code)
};
extern const BlockPhysics BLOCK_PHYSICS[256];
extern const float COLLISION_BOXES[][6];
